    public static class DatabaseSeeder
    {
        public static void EnsureDirectoriesExist(string rootDataPath)
        { 
            if (!Directory.Exists(rootDataPath))
            { Directory.CreateDirectory(rootDataPath); }

            string recipesFolder = Path.Combine(rootDataPath, "Recipes");
            string productsFile = Path.Combine(rootDataPath, "Products.json");
            string categoriesFile = Path.Combine(rootDataPath, "Categories.json");
            string aliasesFile = Path.Combine(rootDataPath, "ProductAliases.json");
            string cookBooksFile = Path.Combine(rootDataPath, "CookBooks.json");
            
            if (!File.Exists(cookBooksFile) || new FileInfo(cookBooksFile).Length == 0)
            {
                try
                {
                    File.WriteAllText(cookBooksFile, "[]");
                }
                catch (Exception ex)
                { }
            }
            if (!Directory.Exists(recipesFolder))
            { Directory.CreateDirectory(recipesFolder); }


            if (!File.Exists(productsFile) || new FileInfo(productsFile).Length == 0)
            { 
                try
                {
                    string json = JsonConvert.SerializeObject(GetDefaultProducts(), Formatting.Indented);
                    File.WriteAllText(productsFile, json);
                }
                catch (Exception ex)
                { }
            }

            if (!File.Exists(categoriesFile) || new FileInfo(categoriesFile).Length == 0)
            { 
                try
                {
                    string json = JsonConvert.SerializeObject(GetDefaultCategories(), Formatting.Indented);
                    File.WriteAllText(categoriesFile, json);
                }
                catch (Exception ex)
                { }
            }

            if (!File.Exists(aliasesFile) || new FileInfo(aliasesFile).Length == 0)
            { 
                try
                {
                    string json = JsonConvert.SerializeObject(GetDefaultProductAliases(), Formatting.Indented);
                    File.WriteAllText(aliasesFile, json);
                }
                catch (Exception ex)
                { }
            }
        }

